use std::cmp::Reverse;
use std::collections::BinaryHeap;

/// Find the best path from src to dst in a directed weighted graph.
/// The graph has vertices 0 .. n-1. Each edge (u, v, w) goes from u to v and
/// costs w. Parallel edges and self-loops are allowed.
///
/// The best path is the one with the smallest total weight; among those, the
/// one with the fewest edges; among those, the lexicographically smallest list
/// of vertices. Return the path as the list of its vertices, from src to dst
/// inclusive. If src == dst the path is [src].
///
/// Return an empty vector when dst cannot be reached from src, and also when
/// the input is invalid: n <= 0, src or dst outside 0 .. n-1, any edge endpoint
/// outside 0 .. n-1, or any negative weight (anywhere in the list, even on an
/// edge no path uses).
/// >>> shortest_path(4, vec![(0, 1, 1), (1, 3, 1), (0, 2, 1), (2, 3, 1)], 0, 3)
/// vec![0, 1, 3]
/// >>> shortest_path(3, vec![(0, 1, 5)], 0, 2)
/// vec![]
fn shortest_path(n: i64, edges: Vec<(i64, i64, i64)>, src: i64, dst: i64) -> Vec<i64> {
    let ok = |x: i64| x >= 0 && x < n;
    if n <= 0 || !ok(src) || !ok(dst) {
        return vec![];
    }
    let mut adj: Vec<Vec<(i64, i64)>> = vec![Vec::new(); n as usize];
    for &(u, v, w) in &edges {
        if !ok(u) || !ok(v) || w < 0 {
            return vec![];
        }
        adj[u as usize].push((v, w));
    }
    // Key (weight, edges, path) only grows along an edge, so Dijkstra's
    // first pop of a vertex is its best path under the full tie-break.
    let mut heap = BinaryHeap::new();
    heap.push(Reverse((0i64, 0i64, vec![src])));
    let mut done = vec![false; n as usize];
    while let Some(Reverse((dist, hops, path))) = heap.pop() {
        let u = *path.last().unwrap();
        if done[u as usize] {
            continue;
        }
        done[u as usize] = true;
        if u == dst {
            return path;
        }
        for &(v, w) in &adj[u as usize] {
            if !done[v as usize] {
                let mut next = path.clone();
                next.push(v);
                heap.push(Reverse((dist + w, hops + 1, next)));
            }
        }
    }
    vec![]
}
